async function updateFetch(url,timeoutMs=10000){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);
  try{
    const response=await fetch(url,{cache:'no-store',mode:'cors',signal:controller.signal});
    if(!response.ok)throw Error('HTTP '+response.status);
    return response;
  }finally{clearTimeout(timer);}
}
async function fetchUpdateVersion(){
  // An old Render deployment can still return HTTP 200 with an outdated
  // version. Compare both tiny metadata feeds and use the newest release.
  const read=async(url,timeout)=>{
    const res=await updateFetch(url,timeout);
    const data=await res.json();
    if(!/^\d+\.\d+\.\d+$/.test(String(data.version||'')))throw Error('bad version');
    return data;
  };
  const [server,mirror]=await Promise.allSettled([
    read(ONLINE_ORIGIN+'/api/version?ts='+Date.now(),5000),
    read(UPDATE_MIRROR_BASE+'version.json?ts='+Date.now(),10000)
  ]);
  if(server.status==='fulfilled' &&
      (mirror.status!=='fulfilled'||compareVersions(server.value.version,mirror.value.version)>=0)){
    updateSource='Render';return server.value;
  }
  if(mirror.status==='fulfilled'){
    updateSource='GitHub';return mirror.value;
  }
  throw new Error('No update metadata available');
}
