async function downloadUpdatedHTML(){
  // A browser cannot overwrite an existing file:// document; save a new copy.
  const preferred=updateSource==='GitHub'?['GitHub','Render']:['Render','GitHub'];
  const version=updateAvailableVersion||CLIENT_VERSION;
  latestBtn.disabled=true;
  showUpdateNotice('📥 最新版HTMLを取得中…',version,true);
  let lastError;
  try{
    for(const source of preferred){
      try{
        const url=source==='GitHub'?UPDATE_MIRROR_BASE+'index.html?ts='+Date.now():ONLINE_ORIGIN+'/download/latest?ts='+Date.now();
        const res=await updateFetch(url,source==='Render'?13000:18000);
        const sizeHeader=Number(res.headers.get('content-length')||0);
        if(sizeHeader>2*1024*1024)throw Error('file too large');
        const page=await res.text();
        if(new Blob([page]).size>2*1024*1024)throw Error('file too large');
        const found=page.match(/const CLIENT_VERSION=['"](\d+\.\d+\.\d+)['"]/);
        if(!found||!page.includes('<!DOCTYPE html>')||compareVersions(found[1],version)<0)throw Error('outdated or invalid HTML');
        const href=URL.createObjectURL(new Blob([page],{type:'text/html;charset=utf-8'}));
        const a=document.createElement('a');
        a.href=href;a.download='BlockPop_ONLINE_v'+found[1]+'.html';a.rel='noopener';
        document.body.appendChild(a);a.click();a.remove();
        setTimeout(()=>URL.revokeObjectURL(href),30000);
        showUpdateNotice('✅ '+source+'から最新版HTMLを取得したよ！保存したファイルを開いてね。',found[1],false);
        return;
      }catch(e){lastError=e;}
    }
    showUpdateNotice('⚠️ 最新版HTMLを取得できなかったよ。インターネット接続を確認してね。',version,true);
  }finally{latestBtn.disabled=false;}
}
